class entity_id;
class po;

typedef short anim_id_t;

enum entity_flavor_t
{
  ENTITY_ENTITY
};

extern const po po_identity_matrix;

class bone
{
public:
  bone();
};

class entity : public bone
{
private:
  void _construct( const entity_id& _id,
                   entity_flavor_t _flavor,
                   anim_id_t _anim_id,
                   unsigned int _flags = 0,
                   const po& _my_po = po_identity_matrix );

public:
  entity( const entity_id& _id,
          entity_flavor_t _flavor,
          unsigned int _flags );
};

entity::entity( const entity_id& _id,
                entity_flavor_t _flavor,
                unsigned int _flags )
  : bone()
{
  _construct( _id, _flavor, (anim_id_t)-1, _flags );
}
